route=re.search(r'LIVE DELIVERY ROUTE: source(\d+) points(\d+) destination(-?\d+)',log);terminal=re.search(r'LIVE DELIVERY TERMINAL: presentations(\d+) sourcecounter(\d+) updates(\d+) completed(\d+) cash(\d+)\.(\d+) active(\d+) pending(-?\d+) waypoint(\d+) clock(-?\d+) rejected(\d+) unavailable(\d+)',log);assert route and terminal
